const MODES = ['uppercase', 'lowercase', 'slug'];

export async function listTools() {
  return [
    {
      name: 'text_transform',
      description: 'Transform text by uppercasing, lowercasing, or slugifying it.',
      inputSchema: {
        type: 'object',
        properties: {
          text: { type: 'string' },
          mode: { type: 'string', enum: MODES },
          trim: { type: 'boolean' },
        },
        required: ['text', 'mode'],
        additionalProperties: false,
      },
    },
  ];
}

function slugify(text) {
  const lower = text.toLowerCase().trim();
  const collapsed = lower.replace(/[^a-z0-9]+/g, '-');
  const stripped = collapsed.replace(/^-+|-+$/g, '');
  return stripped;
}

export async function callTool(name, args) {
  if (name !== 'text_transform') {
    throw new Error('Unknown tool: ' + name);
  }

  if (typeof args !== 'object' || args === null || Array.isArray(args)) {
    throw new Error('Arguments must be an object');
  }

  const allowed = new Set(['text', 'mode', 'trim']);
  for (const key of Object.keys(args)) {
    if (!allowed.has(key)) {
      throw new Error('Unknown argument: ' + key);
    }
  }

  const { text, mode, trim } = args;

  if (typeof text !== 'string') {
    throw new Error('text must be a string');
  }
  if (!MODES.includes(mode)) {
    throw new Error('mode must be one of ' + MODES.join(', '));
  }

  const doTrim = trim === undefined ? true : trim;
  if (typeof doTrim !== 'boolean') {
    throw new Error('trim must be a boolean');
  }

  let out = text;
  if (mode === 'uppercase') {
    out = doTrim ? out.trim().toUpperCase() : out.toUpperCase();
  } else if (mode === 'lowercase') {
    out = doTrim ? out.trim().toLowerCase() : out.toLowerCase();
  } else if (mode === 'slug') {
    out = slugify(doTrim ? out.trim() : out);
  }

  return { content: [{ type: 'text', text: out }] };
}

